import math

def combinations(n, k):
    if k < 0 or k > n:
        return 0
    return math.comb(n, k)

def f(N_R, n):
    return combinations(N_R, 3) + combinations(n - N_R, 3)

n = 7
min_f = float('inf')
best_N_R = -1

for N_R in range(n + 1):
    current_f = f(N_R, n)
    if current_f < min_f:
        min_f = current_f
        best_N_R = N_R

print(f"Minimum value of f(N_R) for n=7 is: {min_f}")
print(f"This minimum occurs when N_R = {best_N_R} or N_R = {n - best_N_R}")
